CREATE TRIGGER cash_binding_inventory_publication_insert AFTER INSERT ON cash_publications BEGIN
      INSERT INTO cash_binding_inventory VALUES(NEW.id,0,0);
    END

CREATE TRIGGER cash_binding_inventory_update AFTER UPDATE ON cash_publication_bindings BEGIN
      UPDATE cash_binding_inventory SET row_count=row_count-1,generation=generation+1 WHERE publication_id=OLD.publication_id; UPDATE cash_binding_inventory SET row_count=row_count+1,generation=generation+1 WHERE publication_id=NEW.publication_id;
    END

