CREATE TRIGGER data_import_count_delete AFTER DELETE ON data_import_rows BEGIN
  UPDATE data_import_run_state_counts SET count=count-1 WHERE run_id=OLD.run_id AND state=OLD.state;
  DELETE FROM data_import_run_state_counts WHERE run_id=OLD.run_id AND state=OLD.state AND count=0;
END

CREATE TRIGGER data_import_count_update AFTER UPDATE OF state,run_id ON data_import_rows
WHEN OLD.state<>NEW.state OR OLD.run_id<>NEW.run_id BEGIN
  UPDATE data_import_run_state_counts SET count=count-1 WHERE run_id=OLD.run_id AND state=OLD.state;
  DELETE FROM data_import_run_state_counts WHERE run_id=OLD.run_id AND state=OLD.state AND count=0;
  INSERT INTO data_import_run_state_counts(run_id,state,count) VALUES(NEW.run_id,NEW.state,1)
    ON CONFLICT(run_id,state) DO UPDATE SET count=count+1;
END

CREATE TRIGGER trg_sales_article_identifier_owner_claim
    BEFORE INSERT ON sales_article_identifiers
    BEGIN
      INSERT OR IGNORE INTO sales_article_identifier_owners (
        canonical_gtin14, product_id, first_source_snapshot_id, created_by, created_at
      ) VALUES (
        NEW.canonical_gtin14, NEW.product_id, NEW.source_snapshot_id,
        NEW.created_by, NEW.created_at
      );
      SELECT CASE WHEN (
        SELECT owner.product_id
        FROM sales_article_identifier_owners owner
        WHERE owner.canonical_gtin14 = NEW.canonical_gtin14
      ) <> NEW.product_id
      THEN RAISE(ABORT, 'sales-article-identifier-owner-conflict') END;
    END
